/* Papers — static client for the GitHub Pages site.
 *
 * Data source: pre-built JSON under data/ (generated by scripts/build_data.py
 * via GitHub Actions). The GitHub API is used only as a fallback when those
 * files are unavailable, and its responses are cached in sessionStorage, so
 * normal browsing never hits the unauthenticated rate limit.
 */
console.log("Running main.js version 9");

const OWNER = "Hiroki11x";
const REPO = "Papers";
const API_BASE = `https://api.github.com/repos/${OWNER}/${REPO}`;
const DATA_BASE = "data";
const PER_PAGE_OPTIONS = [10, 20, 50, 100];
const DEFAULT_PER_PAGE = 20;
const SORT_OPTIONS = [
    { value: "newest", label: "Newest first" },
    { value: "oldest", label: "Oldest first" },
    { value: "updated", label: "Recently updated" },
    { value: "title-asc", label: "Title A → Z" },
    { value: "title-desc", label: "Title Z → A" },
];
const DEFAULT_SORT = "newest";

const container = document.getElementById("issues-container");

// --- In-memory data ----------------------------------------------------------
const store = {
    index: null,      // { generated_at, count, labels:[{name,count,color}], issues:[...] }
    full: null,       // same shape with .body on each issue (lazy, for search)
    fullPromise: null,
    detail: new Map(), // number -> issue with body
};

// --- Fetch helpers -----------------------------------------------------------
async function fetchJson(url) {
    const res = await fetch(url, { cache: "no-cache" });
    if (!res.ok) throw new Error(`${res.status} ${url}`);
    return res.json();
}

function cacheGet(key, maxAgeMs) {
    try {
        const raw = sessionStorage.getItem(key);
        if (!raw) return null;
        const { t, v } = JSON.parse(raw);
        if (Date.now() - t > maxAgeMs) return null;
        return v;
    } catch { return null; }
}
function cacheSet(key, v) {
    try { sessionStorage.setItem(key, JSON.stringify({ t: Date.now(), v })); } catch { /* quota */ }
}

async function apiFetch(path) {
    const key = `gh:${path}`;
    const cached = cacheGet(key, 10 * 60 * 1000);
    if (cached) return cached;
    const res = await fetch(`${API_BASE}${path}`, { headers: { Accept: "application/vnd.github+json" } });
    if (res.status === 403 || res.status === 429) {
        const reset = res.headers.get("X-RateLimit-Reset");
        const when = reset ? ` Try again after ${new Date(reset * 1000).toLocaleTimeString()}.` : "";
        throw new Error(`GitHub API rate limit exceeded.${when}`);
    }
    if (!res.ok) throw new Error(`GitHub API error: ${res.status}`);
    const json = await res.json();
    cacheSet(key, json);
    return json;
}

function normalizeApiIssue(i) {
    return {
        number: i.number,
        title: i.title,
        labels: (i.labels || []).map(l => l.name).sort(),
        state: i.state,
        created_at: i.created_at,
        updated_at: i.updated_at,
        html_url: i.html_url,
        body: i.body || "",
        preview: makePreview(i.body),
    };
}

// Load the lightweight index (static JSON; API fallback).
async function loadIndex() {
    if (store.index) return store.index;
    try {
        store.index = await fetchJson(`${DATA_BASE}/index.json`);
        return store.index;
    } catch (e) {
        console.warn("data/index.json unavailable, falling back to GitHub API", e);
    }
    const issues = [];
    for (let page = 1; page <= 20; page++) {
        const batch = await apiFetch(`/issues?state=open&per_page=100&page=${page}`);
        const onlyIssues = batch.filter(i => !i.pull_request).map(normalizeApiIssue);
        issues.push(...onlyIssues);
        if (batch.length < 100) break;
    }
    const counts = {};
    issues.forEach(i => i.labels.forEach(l => { counts[l] = (counts[l] || 0) + 1; }));
    const labels = Object.entries(counts)
        .map(([name, count]) => ({ name, count, color: "" }))
        .sort((a, b) => b.count - a.count || a.name.localeCompare(b.name));
    store.index = { generated_at: null, count: issues.length, labels, issues, source: "api" };
    store.full = store.index; // API data already includes bodies
    return store.index;
}

// Load the full dataset (with bodies) once, for full-text search.
function loadFull() {
    if (store.full) return Promise.resolve(store.full);
    if (!store.fullPromise) {
        store.fullPromise = fetchJson(`${DATA_BASE}/issues.json`)
            .then(d => { store.full = d; return d; })
            .catch(e => { store.fullPromise = null; throw e; });
    }
    return store.fullPromise;
}

// Load one issue with body (per-issue static file → full dataset → API).
async function loadIssue(number) {
    if (store.detail.has(number)) return store.detail.get(number);
    let issue = null;
    try {
        issue = await fetchJson(`${DATA_BASE}/issues/${number}.json`);
    } catch {
        if (store.full) issue = store.full.issues.find(i => i.number === number) || null;
        if (!issue) issue = normalizeApiIssue(await apiFetch(`/issues/${number}`));
    }
    store.detail.set(number, issue);
    return issue;
}

// --- URL state ---------------------------------------------------------------
function readListState() {
    const p = new URLSearchParams(location.search);
    const per = parseInt(p.get("per") || DEFAULT_PER_PAGE, 10);
    return {
        q: (p.get("q") || "").trim(),
        labels: (p.get("label") || "").split(",").map(s => s.trim()).filter(Boolean),
        sort: SORT_OPTIONS.some(o => o.value === p.get("sort")) ? p.get("sort") : DEFAULT_SORT,
        per: PER_PAGE_OPTIONS.includes(per) ? per : DEFAULT_PER_PAGE,
        page: Math.max(1, parseInt(p.get("page") || "1", 10) || 1),
    };
}

function buildListUrl(s) {
    const p = new URLSearchParams();
    if (s.q) p.set("q", s.q);
    if (s.labels.length) p.set("label", s.labels.join(","));
    if (s.sort !== DEFAULT_SORT) p.set("sort", s.sort);
    if (s.per !== DEFAULT_PER_PAGE) p.set("per", String(s.per));
    if (s.page > 1) p.set("page", String(s.page));
    const qs = p.toString();
    return (qs ? `?${qs}` : location.pathname.split("/").pop() || "./");
}

function navigateTo(url, { replace = false } = {}) {
    if (replace) history.replaceState(null, "", url);
    else history.pushState(null, "", url);
    rememberListUrl();
    router();
}

// --- Filtering / sorting -----------------------------------------------------
function normalizeForSearch(s) {
    return (s || "").toLowerCase().normalize("NFKC");
}

function titleSortKey(title) {
    return normalizeForSearch(title).replace(/^[^\p{L}\p{N}]+/u, "");
}

function applyFilters(issues, s, { searchBodies }) {
    let out = issues;
    if (s.labels.length) {
        out = out.filter(i => s.labels.every(l => i.labels.includes(l)));
    }
    if (s.q) {
        const terms = normalizeForSearch(s.q).split(/\s+/).filter(Boolean);
        out = out.filter(i => {
            const hay = normalizeForSearch(
                `${i.title} #${i.number} ${i.labels.join(" ")} ${searchBodies ? (i.body || "") : (i.preview || "")}`
            );
            return terms.every(t => hay.includes(t));
        });
    }
    const cmp = {
        "newest": (a, b) => b.created_at.localeCompare(a.created_at) || b.number - a.number,
        "oldest": (a, b) => a.created_at.localeCompare(b.created_at) || a.number - b.number,
        "updated": (a, b) => b.updated_at.localeCompare(a.updated_at) || b.number - a.number,
        "title-asc": (a, b) => titleSortKey(a.title).localeCompare(titleSortKey(b.title), "en") || a.number - b.number,
        "title-desc": (a, b) => titleSortKey(b.title).localeCompare(titleSortKey(a.title), "en") || b.number - a.number,
    }[s.sort];
    return [...out].sort(cmp);
}

// --- Router ------------------------------------------------------------------
let routeToken = 0;
async function router() {
    const token = ++routeToken;
    const hash = location.hash;
    if (hash.startsWith("#/issues/")) {
        const n = parseInt(hash.split("/")[2], 10);
        showLoading();
        await renderDetailView(n, token);
    } else {
        await renderListView(readListState(), token);
    }
}

function showLoading(text = "Loading…") {
    container.innerHTML = `
        <div class="loading-container">
            <div class="loading-spinner"></div>
            <p class="loading-text">${escapeHtml(text)}</p>
        </div>`;
}

function showError(err) {
    container.innerHTML = `<div class="error-message"><p>${escapeHtml(err.message || String(err))}</p></div>`;
}

// --- List view ---------------------------------------------------------------
async function renderListView(s, token) {
    try {
        if (!store.index) showLoading();
        const index = await loadIndex();
        if (token !== routeToken) return;

        // Full-text search needs bodies: load lazily, render preview-based
        // results immediately and re-render once bodies arrive.
        let dataset = index.issues;
        let searchBodies = false;
        if (s.q) {
            if (store.full) {
                dataset = store.full.issues;
                searchBodies = true;
            } else {
                loadFull().then(() => { if (token === routeToken) router(); }).catch(() => { });
            }
        }

        const filtered = applyFilters(dataset, s, { searchBodies });
        const totalPages = Math.max(1, Math.ceil(filtered.length / s.per));
        const page = Math.min(s.page, totalPages);
        const pageItems = filtered.slice((page - 1) * s.per, page * s.per);

        const frag = document.createDocumentFragment();
        frag.appendChild(renderSiteIntro(index));
        frag.appendChild(renderToolbar(s, index, { bodiesPending: !!s.q && !searchBodies }));
        frag.appendChild(renderLabelFilter(index.labels, s));
        frag.appendChild(renderResultSummary(filtered.length, page, totalPages, s, index.count));

        if (pageItems.length === 0) {
            const empty = document.createElement("p");
            empty.className = "empty-message";
            empty.textContent = "No notes match the current search / filters.";
            frag.appendChild(empty);
        } else {
            const list = document.createElement("div");
            list.className = "issue-list";
            pageItems.forEach(i => list.appendChild(createIssueCard(i, s)));
            frag.appendChild(list);
        }
        frag.appendChild(renderPagination(page, totalPages, s));

        // Preserve focus/caret in the search box across re-renders.
        const active = document.activeElement;
        const keepFocus = active && active.id === "search-input";
        const caret = keepFocus ? active.selectionStart : null;
        container.replaceChildren(frag);
        if (keepFocus) {
            const input = document.getElementById("search-input");
            input.focus();
            if (caret !== null) input.setSelectionRange(caret, caret);
        }
    } catch (err) {
        if (token === routeToken) showError(err);
    }
}

function renderSiteIntro(index) {
    const intro = document.createElement("section");
    intro.className = "site-intro";
    const updated = index.generated_at
        ? `Data updated ${new Date(index.generated_at).toLocaleString()}`
        : "Live data from the GitHub API";
    intro.innerHTML = `
        <h2>Paper Reading Notes</h2>
        <p>${index.count} notes generated from GitHub Issues. Search, filter by label, and sort below.</p>
        <p class="site-intro-meta">${escapeHtml(updated)}</p>`;
    return intro;
}

function renderToolbar(s, index, { bodiesPending }) {
    const bar = document.createElement("div");
    bar.className = "toolbar";

    // Search
    const searchWrap = document.createElement("div");
    searchWrap.className = "search-wrap";
    const input = document.createElement("input");
    input.type = "search";
    input.id = "search-input";
    input.placeholder = "Search title, labels, body…  ( / to focus )";
    input.value = s.q;
    input.setAttribute("aria-label", "Search notes");
    let timer = null;
    input.addEventListener("input", () => {
        clearTimeout(timer);
        timer = setTimeout(() => {
            navigateTo(buildListUrl({ ...s, q: input.value.trim(), page: 1 }), { replace: true });
        }, 200);
    });
    input.addEventListener("keydown", (e) => {
        if (e.key === "Enter") {
            clearTimeout(timer);
            navigateTo(buildListUrl({ ...s, q: input.value.trim(), page: 1 }), { replace: true });
        }
        if (e.key === "Escape" && input.value) {
            input.value = "";
            navigateTo(buildListUrl({ ...s, q: "", page: 1 }), { replace: true });
        }
    });
    searchWrap.appendChild(input);
    if (bodiesPending) {
        const hint = document.createElement("span");
        hint.className = "search-hint";
        hint.textContent = "Loading full text…";
        searchWrap.appendChild(hint);
    }
    bar.appendChild(searchWrap);

    // Sort
    bar.appendChild(makeSelect("Sort", SORT_OPTIONS, s.sort, v => navigateTo(buildListUrl({ ...s, sort: v, page: 1 }))));
    // Per page
    bar.appendChild(makeSelect("Per page",
        PER_PAGE_OPTIONS.map(n => ({ value: String(n), label: `${n} / page` })),
        String(s.per), v => navigateTo(buildListUrl({ ...s, per: parseInt(v, 10), page: 1 }))));
    return bar;
}

function makeSelect(labelText, options, current, onChange) {
    const wrap = document.createElement("label");
    wrap.className = "select-wrap";
    const span = document.createElement("span");
    span.textContent = labelText;
    const sel = document.createElement("select");
    options.forEach(o => {
        const opt = document.createElement("option");
        opt.value = o.value;
        opt.textContent = o.label;
        if (o.value === current) opt.selected = true;
        sel.appendChild(opt);
    });
    sel.addEventListener("change", () => onChange(sel.value));
    wrap.appendChild(span);
    wrap.appendChild(sel);
    return wrap;
}

function renderLabelFilter(labels, s) {
    const wrap = document.createElement("div");
    wrap.className = "label-filter";

    const all = document.createElement("a");
    all.textContent = "All";
    all.href = buildListUrl({ ...s, labels: [], page: 1 });
    if (s.labels.length === 0) all.classList.add("active");
    all.addEventListener("click", e => { e.preventDefault(); navigateTo(all.href); });
    wrap.appendChild(all);

    labels.forEach(l => {
        const active = s.labels.includes(l.name);
        const next = active ? s.labels.filter(x => x !== l.name) : [...s.labels, l.name];
        const a = document.createElement("a");
        a.href = buildListUrl({ ...s, labels: next, page: 1 });
        a.title = active ? `Remove filter: ${l.name}` : `Filter by ${l.name}${s.labels.length ? " (AND)" : ""}`;
        a.innerHTML = `${escapeHtml(l.name)} <span class="count">${l.count}</span>`;
        if (active) a.classList.add("active");
        a.addEventListener("click", e => { e.preventDefault(); navigateTo(a.href); });
        wrap.appendChild(a);
    });
    return wrap;
}

function renderResultSummary(total, page, totalPages, s, all) {
    const div = document.createElement("div");
    div.className = "result-summary";
    const parts = [];
    parts.push(total === all ? `${total} notes` : `${total} of ${all} notes`);
    if (s.q) parts.push(`matching “${s.q}”`);
    if (s.labels.length) parts.push(`labeled ${s.labels.join(" + ")}`);
    const text = document.createElement("span");
    text.textContent = `${parts.join(" ")} · page ${page} / ${totalPages}`;
    div.appendChild(text);
    if (s.q || s.labels.length) {
        const clear = document.createElement("a");
        clear.href = buildListUrl({ ...s, q: "", labels: [], page: 1 });
        clear.className = "clear-link";
        clear.textContent = "Clear filters";
        clear.addEventListener("click", e => { e.preventDefault(); navigateTo(clear.href); });
        div.appendChild(clear);
    }
    return div;
}

function renderPagination(current, totalPages, s) {
    const nav = document.createElement("nav");
    nav.className = "pagination";
    nav.setAttribute("aria-label", "Pagination");
    if (totalPages <= 1) return nav;

    const link = (page, text, cls = "") => {
        const a = document.createElement("a");
        a.textContent = text;
        if (cls) a.className = cls;
        if (page < 1 || page > totalPages || page === current && cls !== "") {
            a.classList.add("disabled");
            a.setAttribute("aria-disabled", "true");
            return a;
        }
        a.href = buildListUrl({ ...s, page });
        if (page === current) { a.classList.add("current"); a.setAttribute("aria-current", "page"); }
        a.addEventListener("click", e => {
            e.preventDefault();
            navigateTo(a.href);
            window.scrollTo({ top: 0, behavior: "smooth" });
        });
        return a;
    };

    nav.appendChild(link(1, "« First", "nav-edge"));
    nav.appendChild(link(current - 1, "‹ Prev", "nav-edge"));

    // Windowed page numbers: 1 … c-2 c-1 c c+1 c+2 … N
    const pages = new Set([1, totalPages]);
    for (let i = current - 2; i <= current + 2; i++) if (i >= 1 && i <= totalPages) pages.add(i);
    const sorted = [...pages].sort((a, b) => a - b);
    let prev = 0;
    sorted.forEach(p => {
        if (p - prev > 1) {
            const gap = document.createElement("span");
            gap.textContent = "…";
            nav.appendChild(gap);
        }
        nav.appendChild(link(p, String(p)));
        prev = p;
    });

    nav.appendChild(link(current + 1, "Next ›", "nav-edge"));
    nav.appendChild(link(totalPages, "Last »", "nav-edge"));

    // Jump-to-page
    const jump = document.createElement("form");
    jump.className = "page-jump";
    jump.innerHTML = `<label>Go to <input type="number" min="1" max="${totalPages}" value="${current}" aria-label="Page number"></label>`;
    jump.addEventListener("submit", e => {
        e.preventDefault();
        const n = parseInt(jump.querySelector("input").value, 10);
        if (n >= 1 && n <= totalPages) {
            navigateTo(buildListUrl({ ...s, page: n }));
            window.scrollTo({ top: 0, behavior: "smooth" });
        }
    });
    nav.appendChild(jump);
    return nav;
}

// --- Cards -------------------------------------------------------------------
function createIssueCard(issue, s) {
    const card = document.createElement("a");
    card.className = "issue-card";
    card.href = `#/issues/${issue.number}`;

    const title = document.createElement("h2");
    title.innerHTML = highlight(issue.title, s.q);
    card.appendChild(title);
    card.appendChild(createMetaElement(issue));

    const preview = document.createElement("div");
    preview.className = "issue-preview";
    const text = issue.preview || makePreview(issue.body) || "No description provided.";
    preview.innerHTML = highlight(text, s.q);
    card.appendChild(preview);
    return card;
}

function createMetaElement(issue) {
    const meta = document.createElement("div");
    meta.className = "meta";
    const date = document.createElement("span");
    date.className = "date";
    date.textContent = `#${issue.number} · ${new Date(issue.created_at).toLocaleDateString()}`;
    meta.appendChild(date);
    if (issue.labels && issue.labels.length) {
        const tags = document.createElement("div");
        tags.className = "tags";
        issue.labels.forEach(name => {
            const t = document.createElement("span");
            t.className = "tag";
            t.textContent = name;
            tags.appendChild(t);
        });
        meta.appendChild(tags);
    }
    return meta;
}

function highlight(text, q) {
    const safe = escapeHtml(text);
    if (!q) return safe;
    const terms = q.split(/\s+/).filter(Boolean).map(t => t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
    if (!terms.length) return safe;
    return safe.replace(new RegExp(`(${terms.join("|")})`, "gi"), "<mark>$1</mark>");
}

// --- Detail view -------------------------------------------------------------
async function renderDetailView(number, token) {
    try {
        const [issue] = await Promise.all([loadIssue(number), loadIndex().catch(() => null)]);
        if (token !== routeToken) return;

        const frag = document.createDocumentFragment();

        const topNav = document.createElement("div");
        topNav.className = "detail-nav";
        const back = document.createElement("a");
        back.className = "back-link";
        back.href = backToListUrl();
        back.textContent = "← Back to list";
        back.addEventListener("click", e => { e.preventDefault(); navigateTo(back.href); });
        topNav.appendChild(back);
        topNav.appendChild(createNeighborLinks(number));
        frag.appendChild(topNav);

        const card = document.createElement("article");
        card.className = "detail-card";
        const h = document.createElement("h2");
        h.className = "issue-title";
        h.textContent = issue.title;
        card.appendChild(h);
        card.appendChild(createMetaElement(issue));

        const gh = document.createElement("a");
        gh.className = "github-link";
        gh.href = issue.html_url || `https://github.com/${OWNER}/${REPO}/issues/${number}`;
        gh.target = "_blank";
        gh.rel = "noopener noreferrer";
        gh.textContent = "Open on GitHub ↗";
        card.appendChild(gh);

        const body = document.createElement("div");
        body.className = "issue-body markdown-body";
        body.innerHTML = renderMarkdown(issue.body);
        card.appendChild(body);
        frag.appendChild(card);

        container.replaceChildren(frag);
        document.title = `${issue.title} | Papers`;
        window.scrollTo({ top: 0 });
    } catch (err) {
        if (token === routeToken) showError(err);
    }
}

// Remember the list URL the user came from so "Back" restores filters/page.
let lastListUrl = null;
function backToListUrl() {
    return lastListUrl || "./";
}

function createNeighborLinks(number) {
    const wrap = document.createElement("div");
    wrap.className = "neighbor-links";
    if (!store.index) return wrap;
    const nums = store.index.issues.map(i => i.number).sort((a, b) => a - b);
    const idx = nums.indexOf(number);
    const mk = (n, text) => {
        const a = document.createElement("a");
        a.textContent = text;
        if (n == null) { a.classList.add("disabled"); return a; }
        a.href = `#/issues/${n}`;
        a.title = store.index.issues.find(i => i.number === n)?.title || "";
        return a;
    };
    wrap.appendChild(mk(idx > 0 ? nums[idx - 1] : null, "‹ Older"));
    wrap.appendChild(mk(idx >= 0 && idx < nums.length - 1 ? nums[idx + 1] : null, "Newer ›"));
    return wrap;
}

// --- Markdown ----------------------------------------------------------------
// Prefer marked + DOMPurify (loaded from CDN in index.html); fall back to a
// small built-in parser if they failed to load.
function renderMarkdown(md) {
    if (!md) return "<p>No description provided.</p>";
    if (window.marked && window.DOMPurify) {
        const html = window.marked.parse(md, { gfm: true, breaks: true });
        return window.DOMPurify.sanitize(html, { ADD_ATTR: ["target"] });
    }
    return parseMarkdownBasic(md);
}

function parseMarkdownBasic(markdown) {
    const codeBlocks = [];
    let text = markdown.replace(/```(\w+)?\n([\s\S]*?)```/g, (_m, lang, code) => {
        const ph = `%%CODEBLOCK_${codeBlocks.length}%%`;
        codeBlocks.push(`<pre class="code-block ${lang || ""}"><code>${escapeHtml(code.trim())}</code></pre>`);
        return ph;
    });
    const out = [];
    let list = null;
    let quote = [];
    const flushList = () => { if (list) { out.push(`<${list.type}>${list.items.map(i => `<li>${i}</li>`).join("")}</${list.type}>`); list = null; } };
    const flushQuote = () => { if (quote.length) { out.push(`<blockquote>${quote.join("<br>")}</blockquote>`); quote = []; } };
    for (const line of text.split("\n")) {
        if (line.trim().startsWith("%%CODEBLOCK_")) { flushList(); flushQuote(); out.push(line.trim()); continue; }
        const bq = line.match(/^>\s?(.*)/);
        if (bq) { flushList(); quote.push(inline(bq[1])); continue; } else flushQuote();
        const h = line.match(/^(#{1,6})\s+(.*)/);
        if (h) { flushList(); out.push(`<h${h[1].length}>${inline(h[2])}</h${h[1].length}>`); continue; }
        if (/^(---|\*\*\*)$/.test(line.trim())) { flushList(); out.push("<hr>"); continue; }
        const ul = line.match(/^[\*\-\+]\s+(.*)/);
        if (ul) { if (list && list.type === "ul") list.items.push(inline(ul[1])); else { flushList(); list = { type: "ul", items: [inline(ul[1])] }; } continue; }
        const ol = line.match(/^\d+\.\s+(.*)/);
        if (ol) { if (list && list.type === "ol") list.items.push(inline(ol[1])); else { flushList(); list = { type: "ol", items: [inline(ol[1])] }; } continue; }
        if (line.trim() === "") { flushList(); continue; }
        flushList();
        out.push(`<p>${inline(line)}</p>`);
    }
    flushList(); flushQuote();
    let html = out.join("\n");
    codeBlocks.forEach((b, i) => { html = html.replace(`<p>%%CODEBLOCK_${i}%%</p>`, b).replace(`%%CODEBLOCK_${i}%%`, b); });
    return html;

    function inline(t) {
        return t
            .replace(/`([^`]+)`/g, '<code class="inline-code">$1</code>')
            .replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img src="$2" alt="$1" class="markdown-image">')
            .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>')
            .replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>")
            .replace(/__(.*?)__/g, "<strong>$1</strong>")
            .replace(/\*([^\*]+)\*/g, "<em>$1</em>")
            .replace(/_([^_]+)_/g, "<em>$1</em>");
    }
}

function makePreview(body) {
    if (!body) return "";
    let t = body
        .replace(/```[\s\S]*?```/g, " ")
        .replace(/<[^>]+>/g, " ")
        .replace(/!\[[^\]]*\]\([^)]*\)/g, " ")
        .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1")
        .replace(/https?:\/\/\S+/g, " ")
        .replace(/[#>*_`|]/g, " ")
        .replace(/\s+/g, " ")
        .trim();
    if (t.length > 160) t = t.slice(0, 160).trimEnd() + "…";
    return t;
}

function escapeHtml(text) {
    const div = document.createElement("div");
    div.textContent = text == null ? "" : String(text);
    return div.innerHTML;
}

// --- Events ------------------------------------------------------------------
function rememberListUrl() {
    if (!location.hash.startsWith("#/issues/")) {
        lastListUrl = location.search || "./";
        document.title = "Papers | Reading Notes";
    }
}
// popstate also fires for hash navigation, so a separate hashchange listener
// would run the router twice.
window.addEventListener("popstate", () => { rememberListUrl(); router(); });
document.addEventListener("DOMContentLoaded", () => { rememberListUrl(); router(); });
document.addEventListener("keydown", (e) => {
    if (e.key === "/" && !/input|textarea|select/i.test(document.activeElement?.tagName || "")) {
        const input = document.getElementById("search-input");
        if (input) { e.preventDefault(); input.focus(); input.select(); }
    }
});
